/* =====================================================================================
 FFL dealer directory: legacy PHP dealer data -> FflDealers / ZipGeocodes
 GENERATED from the PHP repo's database/sqlserver/02_dealer_tables_data.sql (MySQL hk_parts export of
 ffl_database / dealer_data / geocode_cache, 2026-11-16). Self-contained: the legacy ffl_* / dealer_data /
 geocode_cache tables are NOT needed and are not created. Large file, run with sqlcmd:
   sqlcmd -S <server> -d <database> -E -f 65001 -i 25_2026-11-16_ImportLegacyFflDealers.sql

 1. Creates FflDealers and ZipGeocodes when they do not exist (same shape as migration AddFflDealerShipping,
    which skips creating them when they already exist, so this can run before or after the app migrates).
 2. ZipGeocodes: 1803 ZIP centres from geocode_cache (zip_only rows; ZIP+4 trimmed to 5 digits; latest row
    per ZIP; Source = 'Legacy').
 3. FflDealers: 78108 dealers from ffl_database, mapped onto our columns:
      Key = lic_regn + lic_dist (2 digits) + lic_seqn (5 digits), identical to the legacy [key] for every row.
      lic_dist / lic_cnty / lic_type were INT in MySQL and lost their leading zeros: padded back to 2 / 3 / 2
      digits ("1" -> "01") so licence numbers print R-DD-CCC-TT-XX-SSSSS and the transfer-type filter matches.
      Empty strings -> NULL. IsActive = 1.
      dealer_data -> AllowsTransfers / LastTransferFee / AverageReviewRating (1 matched; 1 row(s) name a
      dealer that is not in the export and are skipped).
      165 dealers without a position in the export get their ZIP centre; 713 stay without one
      (geocode them from Admin > Shipping > FFL Dealers).
 Not imported: ffl_region / ffl_district (reference names with no counterpart in our model), ffl_type (empty).
 Insert-only and idempotent: rows whose Key / Zip already exist are left untouched (so dealer data an admin
 maintains here is never overwritten). Safe to re-run. Refresh existing dealers with the ATF file on the admin
 FFL Dealers page.
 Do not hand-edit: regenerate from the source export.
 ===================================================================================== */

SET NOCOUNT ON;
SET XACT_ABORT ON;
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
SET DATEFORMAT ymd;
GO

/* ---------- 1. Tables ---------- */
IF OBJECT_ID(N'[FflDealers]', N'U') IS NULL
BEGIN
    CREATE TABLE [FflDealers] (
        [Id] uniqueidentifier NOT NULL,
        [Key] nvarchar(20) NOT NULL,
        [LicRegn] nvarchar(2) NOT NULL,
        [LicDist] nvarchar(3) NOT NULL,
        [LicCnty] nvarchar(5) NOT NULL,
        [LicType] nvarchar(3) NOT NULL,
        [LicXprdte] nvarchar(4) NOT NULL,
        [LicSeqn] nvarchar(10) NOT NULL,
        [LicenseName] nvarchar(255) NULL,
        [BusinessName] nvarchar(255) NULL,
        [PremiseStreet] nvarchar(200) NULL,
        [PremiseCity] nvarchar(100) NULL,
        [PremiseState] nvarchar(50) NULL,
        [PremiseZipCode] nvarchar(20) NULL,
        [MailStreet] nvarchar(200) NULL,
        [MailCity] nvarchar(100) NULL,
        [MailState] nvarchar(50) NULL,
        [MailZipCode] nvarchar(20) NULL,
        [VoicePhone] nvarchar(30) NULL,
        [Latitude] float NULL,
        [Longitude] float NULL,
        [IsActive] bit NOT NULL,
        [LastImportedOnUtc] datetime2 NULL,
        [AllowsTransfers] bit NULL,
        [LastTransferFee] decimal(18,2) NULL,
        [AverageReviewRating] decimal(5,2) NULL,
        [DealerDataUpdatedOnUtc] datetime2 NULL,
        [CreatedById] uniqueidentifier NULL,
        [CreatedOnUtc] datetime2 NOT NULL,
        [UpdatedById] uniqueidentifier NULL,
        [UpdatedOnUtc] datetime2 NOT NULL,
        CONSTRAINT [PK_FflDealers] PRIMARY KEY ([Id])
    );
    CREATE UNIQUE INDEX [IX_FflDealers_Key] ON [FflDealers] ([Key]);
    CREATE INDEX [IX_FflDealers_LicType_Latitude_Longitude] ON [FflDealers] ([LicType], [Latitude], [Longitude]) INCLUDE ([IsActive], [AllowsTransfers]);
    CREATE INDEX [IX_FflDealers_PremiseZipCode] ON [FflDealers] ([PremiseZipCode]);
END;
GO
IF OBJECT_ID(N'[ZipGeocodes]', N'U') IS NULL
BEGIN
    CREATE TABLE [ZipGeocodes] (
        [Id] uniqueidentifier NOT NULL,
        [Zip] nvarchar(10) NOT NULL,
        [Latitude] float NOT NULL,
        [Longitude] float NOT NULL,
        [Source] nvarchar(30) NOT NULL,
        [CreatedById] uniqueidentifier NULL,
        [CreatedOnUtc] datetime2 NOT NULL,
        [UpdatedById] uniqueidentifier NULL,
        [UpdatedOnUtc] datetime2 NOT NULL,
        CONSTRAINT [PK_ZipGeocodes] PRIMARY KEY ([Id])
    );
    CREATE UNIQUE INDEX [IX_ZipGeocodes_Zip] ON [ZipGeocodes] ([Zip]);
END;
GO

IF OBJECT_ID(N'tempdb..#ImportCounts') IS NOT NULL DROP TABLE #ImportCounts;
CREATE TABLE #ImportCounts (Tbl nvarchar(20) NOT NULL, Inserted int NOT NULL);
GO

